	"testing"
)

// 提议顺序的完整断言辅助：提议的交易标识序列必须与 want 完全一致。
func assertProposalOrder(t *testing.T, n *Node, want []string) ProposalView {
	t.Helper()
	p, err := n.Propose()
	if err != nil {
		t.Fatal(err)
	}
	if fmt.Sprint(p.TxIDs) != fmt.Sprint(want) {
